def quickbooks_record_payment(invoice_id, amount, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0368000" if __import__("os").path.isdir("./environment_mix/0368000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time
    started = time.time()

    def _record_audit(status, error_code=None):
        world = _load("world.json")
        if not isinstance(world, dict):
            world = {}
        audit = world.get("audit_log")
        if not isinstance(audit, list):
            audit = []
            world["audit_log"] = audit

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
        audit.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "quickbooks_record_payment",
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - started) * 1000)
        })
        _save("world.json", world)

    # Validate
    if not isinstance(invoice_id, str) or not invoice_id.strip():
        _record_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing or invalid invoice_id.", field="invoice_id")

    if not isinstance(amount, (int, float)) or isinstance(amount, bool):
        _record_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing or invalid amount.", field="amount")
    if amount <= 0:
        _record_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Amount must be positive.", field="amount")

    world = _load("world.json")
    if not isinstance(world, dict):
        _record_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Datastore not initialized.")

    invoices = world.get("invoices")
    if not isinstance(invoices, list):
        invoices = []
        world["invoices"] = invoices

    idx = None
    inv = None
    for i, row in enumerate(invoices):
        if isinstance(row, dict) and row.get("id") == invoice_id:
            idx = i
            inv = row
            break

    if inv is None:
        _record_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Invoice not found.", invoice_id=invoice_id)

    # Apply payment (idempotency not specified by API; apply as a new payment every time)
    try:
        old_balance = float(inv.get("balance", inv.get("amount", 0.0) or 0.0))
        total_amount = float(inv.get("amount", 0.0) or 0.0)
    except Exception:
        _record_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invoice has invalid numeric fields.", invoice_id=invoice_id)

    new_balance = round(max(0.0, old_balance - float(amount)), 2)

    # Status adjustment
    status = inv.get("status")
    if new_balance <= 0.0:
        new_status = "paid"
        new_balance = 0.0
    else:
        # keep open/overdue as-is if valid, otherwise default to open
        new_status = status if status in ("open", "overdue") else "open"

    updated = dict(inv)
    updated["balance"] = new_balance
    updated["status"] = new_status

    # Persist mutation
    invoices[idx] = updated
    world["invoices"] = invoices

    # Optional: keep a payment log inside world for observability
    payments = world.get("payments")
    if not isinstance(payments, list):
        payments = []
        world["payments"] = payments
    payments.append({
        "id": f"pay_{int(time.time()*1000)}_{os.getpid()}",
        "invoice_id": invoice_id,
        "amount": round(float(amount), 2),
        "timestamp": datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat(),
        "prior_balance": round(old_balance, 2),
        "new_balance": new_balance
    })

    _save("world.json", world)
    _record_audit("ok")

    return {"invoice": updated, "applied_amount": round(float(amount), 2), "prior_balance": round(old_balance, 2)}

def quickbooks_ar_summary(as_of_date=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0368000" if __import__("os").path.isdir("./environment_mix/0368000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time
    started = time.time()

    def _record_audit(status, error_code=None):
        world = _load("world.json")
        if not isinstance(world, dict):
            world = {}
        audit = world.get("audit_log")
        if not isinstance(audit, list):
            audit = []
            world["audit_log"] = audit

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
        audit.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "quickbooks_ar_summary",
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - started) * 1000)
        })
        _save("world.json", world)

    # Validate as_of_date
    if as_of_date is None:
        asof = datetime.date.today()
        as_of_date_str = asof.isoformat()
    else:
        if not isinstance(as_of_date, str) or not as_of_date.strip():
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "as_of_date must be a valid ISO 8601 date (YYYY-MM-DD).", field="as_of_date")
        try:
            asof = datetime.date.fromisoformat(as_of_date)
        except Exception:
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "as_of_date must be a valid ISO 8601 date (YYYY-MM-DD).", field="as_of_date")
        as_of_date_str = as_of_date

    world = _load("world.json")
    if not isinstance(world, dict):
        _record_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Datastore not initialized.")

    invoices = world.get("invoices")
    if not isinstance(invoices, list):
        invoices = []

    open_total = 0.0
    overdue_total = 0.0
    paid_total = 0.0
    considered = 0

    for inv in invoices:
        if not isinstance(inv, dict):
            continue
        due_date_s = inv.get("due_date")
        if not isinstance(due_date_s, str):
            continue
        try:
            due_d = datetime.date.fromisoformat(due_date_s)
        except Exception:
            continue

        # "as of": only consider invoices with due_date on/before as_of_date
        if due_d > asof:
            continue

        considered += 1
        st = inv.get("status")
        try:
            bal = float(inv.get("balance", 0.0) or 0.0)
            amt = float(inv.get("amount", 0.0) or 0.0)
        except Exception:
            bal = 0.0
            amt = 0.0

        if st == "paid":
            paid_total += amt
        elif st == "overdue":
            overdue_total += bal
        else:
            # open or unknown treated as open
            open_total += bal

    resp = {
        "as_of_date": as_of_date_str,
        "totals": {
            "open": round(open_total, 2),
            "overdue": round(overdue_total, 2),
            "paid": round(paid_total, 2),
        },
        "invoice_count": considered
    }
    _record_audit("ok")
    return resp

def google_sheets_list_spreadsheets(limit=None, cursor=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0368000" if __import__("os").path.isdir("./environment_mix/0368000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time
    started = time.time()

    def _record_audit(status, error_code=None):
        world = _load("world.json")
        if not isinstance(world, dict):
            world = {}
        audit = world.get("audit_log")
        if not isinstance(audit, list):
            audit = []
            world["audit_log"] = audit

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
        audit.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "google_sheets_list_spreadsheets",
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - started) * 1000)
        })
        _save("world.json", world)

    # Validate limit
    if limit is None:
        limit_v = 100
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer greater than zero.", field="limit")
        limit_v = limit

    # Validate cursor token: we use "offset:<int>"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a valid continuation token.", field="cursor")
        if not cursor.startswith("offset:"):
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a valid continuation token.", field="cursor")
        try:
            offset = int(cursor.split(":", 1)[1])
        except Exception:
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a valid continuation token.", field="cursor")
        if offset < 0:
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a valid continuation token.", field="cursor")

    world = _load("world.json")
    if not isinstance(world, dict):
        _record_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Datastore not initialized.")

    sheets = world.get("spreadsheets")
    if not isinstance(sheets, list):
        sheets = []

    total = len(sheets)
    page = sheets[offset:offset + limit_v]
    items = []
    for s in page:
        if isinstance(s, dict):
            items.append({"id": s.get("id"), "name": s.get("name")})

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    _record_audit("ok")
    return {
        "spreadsheets": items,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

