    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time
    started = time.time()

    def _record_audit(status, error_code=None):
        world = _load("world.json")
        if not isinstance(world, dict):
            world = {}
        audit = world.get("audit_log")
        if not isinstance(audit, list):
            audit = []
            world["audit_log"] = audit

