        audit.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "gmail_find_email",
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - started) * 1000)
        })
        _save("world.json", world)

    # Validate params
    if from_contains is not None and not isinstance(from_contains, str):
        _record_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_contains must be a string.", field="from_contains")
    if subject_contains is not None and not isinstance(subject_contains, str):
        _record_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subject_contains must be a string.", field="subject_contains")
    if label is not None and not isinstance(label, str):
        _record_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a string.", field="label")

    world = _load("world.json")
    if not isinstance(world, dict):
        _record_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Datastore not initialized.")

    messages = world.get("messages")
    if not isinstance(messages, list):
        messages = []

    # Validate label exists if provided
    if label is not None:
        existing_labels = set()
        for m in messages:
            if isinstance(m, dict):
                lids = m.get("label_ids")
                if isinstance(lids, list):
                    for lid in lids:
                        if isinstance(lid, str):
                            existing_labels.add(lid)
        if label not in existing_labels:
            _record_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported label value.", field="label", supported=sorted(existing_labels))

    out = []
    fc = from_contains.lower() if isinstance(from_contains, str) else None
    sc = subject_contains.lower() if isinstance(subject_contains, str) else None
    for m in messages:
        if not isinstance(m, dict):
            continue
        if label is not None:
            lids = m.get("label_ids")
            if not (isinstance(lids, list) and label in lids):
                continue
        if fc:
            if fc not in (m.get("from_") or "").lower():
                continue
        if sc:
            if sc not in (m.get("subject") or "").lower():
                continue
        out.append(m)

    _record_audit("ok")
    return {"messages": out, "total": len(out)}

